var POOL_ADDRESSES = {
  WETHUSDC: "0x58013521Ba2D0FdfDC4763313Ae4e61A4dD9438e",
  "WETH/USDC": "0x58013521Ba2D0FdfDC4763313Ae4e61A4dD9438e",
  WBTCUSDC: "0x66b50d56c4275e59dAC301f51E3906C5391c7131",
  "WBTC/USDC": "0x66b50d56c4275e59dAC301f51E3906C5391c7131"
};

class MarketService {
  getPoolAddress(symbol) {
    const normalizedSymbol = symbol.toUpperCase().replace("/", "");
    const poolAddress = POOL_ADDRESSES[normalizedSymbol] || POOL_ADDRESSES[symbol];
    if (!poolAddress) {
      throw new Error(`Unsupported symbol: ${symbol}`);
    }
    return poolAddress.toLowerCase();
  }
  async getOpenOrders(symbol, address) {
    const poolAddress = this.getPoolAddress(symbol);
    const result = await db.select().from(orders).where(and(eq(orders.poolId, poolAddress), eq(orders.user, address.toLowerCase()), eq(orders.status, "Open"))).orderBy(desc(orders.timestamp));
    return result.map((order) => ({
      id: order.id,
      orderId: order.orderId.toString(),
      user: order.user,
      side: order.side?.toLowerCase(),
      price: order.price?.toString() || "0",
      quantity: order.quantity?.toString() || "0",
      filled: order.filled?.toString() || "0",
      status: order.status?.toLowerCase(),
      expiry: order.expiry?.toString() || "0",
      isMarketOrder: order.orderType === "Market",
      timestamp: order.timestamp?.toString()
    }));
  }
  async getAllOrders(symbol, address, limit = 50) {
    const poolAddress = this.getPoolAddress(symbol);
    const result = await db.select().from(orders).where(and(eq(orders.poolId, poolAddress), eq(orders.user, address.toLowerCase()))).orderBy(desc(orders.timestamp)).limit(limit);
    return result.map((order) => ({
      id: order.id,
      orderId: order.orderId.toString(),
      user: order.user,
      side: order.side?.toLowerCase(),
      price: order.price?.toString() || "0",
      quantity: order.quantity?.toString() || "0",
      filled: order.filled?.toString() || "0",
      status: order.status?.toLowerCase(),
      expiry: order.expiry?.toString() || "0",
      isMarketOrder: order.orderType === "Market",
      timestamp: order.timestamp?.toString()
    }));
  }
  async getTrades(symbol, limit = 100, user) {
    const poolAddress = this.getPoolAddress(symbol);
    let query = db.select().from(orderBookTrades).where(eq(orderBookTrades.poolId, poolAddress));
    const result = await query.orderBy(desc(orderBookTrades.timestamp)).limit(limit);
    return result.map((trade) => ({
      id: trade.id,
      buyOrderId: trade.id,
      sellOrderId: trade.id,
      user: user || "",
      side: trade.side?.toLowerCase(),
      price: trade.price?.toString() || "0",
      quantity: trade.quantity?.toString() || "0",
      timestamp: trade.timestamp?.toString() || "0"
    }));
  }
  async getDepth(symbol, limit = 20) {
    const poolAddress = this.getPoolAddress(symbol);
    const buyOrders = await db.select().from(orderBookDepth).where(and(eq(orderBookDepth.poolId, poolAddress), eq(orderBookDepth.side, "Buy"))).orderBy(desc(orderBookDepth.price)).limit(limit);
    const sellOrders = await db.select().from(orderBookDepth).where(and(eq(orderBookDepth.poolId, poolAddress), eq(orderBookDepth.side, "Sell"))).orderBy(asc(orderBookDepth.price)).limit(limit);
    return {
      lastUpdateId: Date.now(),
      bids: buyOrders.map((order) => [
        order.price.toString(),
        order.quantity.toString()
      ]),
      asks: sellOrders.map((order) => [
        order.price.toString(),
        order.quantity.toString()
      ])
    };
  }
  async getPairs() {
    const result = await db.select().from(pools);
    return result.map((pool) => ({
      id: pool.id,
      poolId: pool.poolId,
      baseAsset: pool.baseCurrency,
      quoteAsset: pool.quoteCurrency,
      baseCurrency: pool.baseCurrency,
      quoteCurrency: pool.quoteCurrency,
      orderBook: pool.orderBook,
      price: pool.price?.toString(),
      volume24h: pool.volume?.toString(),
      baseDecimals: pool.baseDecimals,
      quoteDecimals: pool.quoteDecimals,
      volume: pool.volume?.toString(),
      volumeInQuote: pool.volumeInQuote?.toString() || "0",
      timestamp: pool.timestamp
    }));
  }
  async getTickerPrice(symbol) {
    const poolAddress = this.getPoolAddress(symbol);
    const latestTrade = await db.select().from(orderBookTrades).where(eq(orderBookTrades.poolId, poolAddress)).orderBy(desc(orderBookTrades.timestamp)).limit(1);
    if (latestTrade.length > 0) {
      return {
        symbol,
        price: latestTrade[0].price?.toString() || "0"
      };
    }
    const pool = await db.select().from(pools).where(eq(pools.poolId, poolAddress)).limit(1);
    if (pool.length === 0) {
      return null;
    }
    return {
      symbol,
      price: pool[0].price?.toString() || "0"
    };
  }
  async getTicker24Hr(symbol) {
    const poolAddress = this.getPoolAddress(symbol);
    const now = Math.floor(Date.now() / 1000);
    const oneDayAgo = now - 86400;
    const trades2 = await db.select().from(orderBookTrades).where(and(eq(orderBookTrades.poolId, poolAddress), gte(orderBookTrades.timestamp, oneDayAgo))).orderBy(asc(orderBookTrades.timestamp));
    if (trades2.length === 0) {
      return {
        symbol,
        priceChange: "0",
        priceChangePercent: "0",
        lastPrice: "0",
        volume: "0",
        quoteVolume: "0",
        openPrice: "0",
        highPrice: "0",
        lowPrice: "0",
        count: 0
      };
    }
    const prices = trades2.map((t2) => BigInt(t2.price || 0));
    const volumes = trades2.map((t2) => BigInt(t2.quantity || 0));
    const lastPrice = prices[prices.length - 1];
    const openPrice = prices[0];
    const highPrice = prices.reduce((a, b) => a > b ? a : b);
    const lowPrice = prices.reduce((a, b) => a < b ? a : b);
    const volume = volumes.reduce((a, b) => a + b, 0n);
    const priceChange = lastPrice - openPrice;
    const priceChangePercent = openPrice > 0n ? Number(priceChange * 10000n / openPrice) / 100 : 0;
    return {
      symbol,
      priceChange: priceChange.toString(),
      priceChangePercent: priceChangePercent.toFixed(2),
      lastPrice: lastPrice.toString(),
      volume: volume.toString(),
      quoteVolume: (volume * lastPrice).toString(),
      openPrice: openPrice.toString(),
      highPrice: highPrice.toString(),
      lowPrice: lowPrice.toString(),
      count: trades2.length
    };
  }
  async getKlines(symbol, interval2, limit = 500, startTime, endTime) {
    const poolAddress = this.getPoolAddress(symbol);
    const bucketTable = this.getBucketTable(interval2);
    let query = db.select().from(bucketTable).where(eq(bucketTable.poolId, poolAddress));
    if (startTime) {
      query = query.where(gte(bucketTable.openTime, startTime));
    }
    if (endTime) {
      query = query.where(lte(bucketTable.closeTime, endTime));
    }
    const result = await query.orderBy(desc(bucketTable.openTime)).limit(limit);
    return result.map((bucket) => ({
      t: bucket.openTime * 1000,
      T: bucket.closeTime * 1000,
      o: bucket.openPrice.toString(),
      h: bucket.highPrice.toString(),
      l: bucket.lowPrice.toString(),
      c: bucket.closePrice.toString(),
      v: bucket.volume.toString(),
      q: bucket.quoteVolume.toString(),
      n: bucket.count,
      V: bucket.takerBuyBaseVolume.toString(),
      Q: bucket.takerBuyQuoteVolume.toString()
    })).reverse();
  }
  getBucketTable(interval2) {
    switch (interval2) {
      case "1m":
        return minuteBuckets;
      case "5m":
        return fiveMinuteBuckets;
      case "30m":
        return thirtyMinuteBuckets;
      case "1h":
        return hourBuckets;
      case "1d":
        return dailyBuckets;
      default:
        return minuteBuckets;
    }
  }
  async getBalances(address) {
    const result = await db.select().from(balances).where(eq(balances.user, address.toLowerCase()));
    return result.map((balance) => ({
      currency: balance.currency,
      available: balance.amount?.toString() || "0",
      locked: balance.lockedAmount?.toString() || "0",
      total: ((balance.amount || 0n) + (balance.lockedAmount || 0n)).toString()
    }));
  }
}
