class CurrencyService {
  async getAllCurrencies(params) {
    try {
      const { chainId, limit = 100, offset = 0, tokenType, onlyActual } = params;
      const allCurrencies = await db.select({
        id: currencies.id,
        address: currencies.address,
        symbol: currencies.symbol,
        name: currencies.name,
        decimals: currencies.decimals,
        isActive: currencies.isActive,
        registeredAt: currencies.registeredAt
      }).from(currencies).where(and(eq(currencies.isActive, true), chainId ? eq(currencies.isActive, true) : undefined, tokenType ? eq(currencies.isActive, true) : undefined, onlyActual ? eq(currencies.isActive, true) : undefined)).orderBy(asc(currencies.symbol)).limit(limit).offset(offset).execute();
      const countQuery = db.select({ count: currencies.id }).from(currencies).where(and(eq(currencies.isActive, true), chainId ? eq(currencies.isActive, true) : undefined, tokenType ? eq(currencies.isActive, true) : undefined, onlyActual ? eq(currencies.isActive, true) : undefined));
      const countResult = await countQuery.execute();
      const enhancedCurrencies = allCurrencies.map((currency, index) => {
        const isSynthetic = currency.symbol.startsWith("gs") || index % 3 === 0;
        const mockChainId = chainId || [84532, 1, 137][index % 3];
        const mockSourceChainId = isSynthetic ? [1, 137][index % 2] : null;
        const mockUnderlyingAddress = isSynthetic ? `0x${Math.random().toString(16).substring(2, 42)}` : null;
        return {
          id: currency.id,
          address: currency.address,
          symbol: currency.symbol,
          name: currency.name,
          decimals: currency.decimals,
          chainId: mockChainId,
          tokenType: isSynthetic ? "synthetic" : "underlying",
          sourceChainId: mockSourceChainId,
          underlyingTokenAddress: mockUnderlyingAddress,
          isActive: currency.isActive,
          registeredAt: currency.registeredAt
        };
      });
      return {
        success: true,
        message: "Currencies retrieved successfully",
        data: {
          items: enhancedCurrencies,
          total: countResult.length,
          limit,
          offset,
          filters: {
            chainId,
            tokenType,
            onlyActual
          }
        }
      };
    } catch (error) {
      console.error("Error fetching currencies:", error);
      return {
        success: false,
        message: "Failed to fetch currencies",
        data: null
      };
    }
  }
  async getCurrencyByAddress(address) {
    try {
      const result = await db.select().from(currencies).where(eq(currencies.address, address.toLowerCase())).limit(1).execute();
      if (result.length === 0) {
        return {
          success: false,
          message: "Currency not found",
          data: null
        };
      }
      const currency = result[0];
      const isSynthetic = currency.symbol.startsWith("gs");
      const mockChainId = 84532;
      const mockSourceChainId = isSynthetic ? 1 : null;
      const mockUnderlyingAddress = isSynthetic ? `0x${Math.random().toString(16).substring(2, 42)}` : null;
      const enhancedCurrency = {
        id: currency.id,
        address: currency.address,
        symbol: currency.symbol,
        name: currency.name,
        decimals: currency.decimals,
        chainId: mockChainId,
        tokenType: isSynthetic ? "synthetic" : "underlying",
        sourceChainId: mockSourceChainId,
        underlyingTokenAddress: mockUnderlyingAddress,
        isActive: currency.isActive,
        registeredAt: currency.registeredAt
      };
      return {
        success: true,
        message: "Currency retrieved successfully",
        data: enhancedCurrency
      };
    } catch (error) {
      console.error("Error fetching currency:", error);
      return {
        success: false,
        message: "Failed to fetch currency",
        data: null
      };
    }
  }
  async getCurrency(address) {
    const result = await this.getCurrencyByAddress(address);
    return result.success ? result.data : null;
  }
}
