class RateLimitService {
  static instance;
  constructor() {}
  static getInstance() {
    if (!RateLimitService.instance) {
      RateLimitService.instance = new RateLimitService;
    }
    return RateLimitService.instance;
  }
  async checkBothLimits(address, ip2, maxRequests = 3, windowMs = 60 * 60 * 1000, cooldownMs = 4 * 60 * 60 * 1000) {
    const now = new Date;
    const windowStart = new Date(now.getTime() - windowMs);
    const addressLimit = await this.checkRateLimit(address.toLowerCase(), "address", maxRequests, windowStart, now);
    if (!addressLimit.allowed) {
      return {
        allowed: false,
        reason: "ADDRESS_RATE_LIMIT",
        remaining: addressLimit.remaining,
        resetTime: addressLimit.resetTime,
        remainingCooldown: 0
      };
    }
    const ipLimit = await this.checkRateLimit(ip2, "ip", maxRequests, windowStart, now);
    if (!ipLimit.allowed) {
      return {
        allowed: false,
        reason: "IP_RATE_LIMIT",
        remaining: ipLimit.remaining,
        resetTime: ipLimit.resetTime,
        remainingCooldown: 0
      };
    }
    const addressCooldown = await this.checkCooldown(address.toLowerCase(), "address", now);
    if (!addressCooldown.allowed) {
      return {
        allowed: false,
        reason: "ADDRESS_COOLDOWN",
        remaining: addressLimit.remaining,
        resetTime: addressLimit.resetTime,
        remainingCooldown: addressCooldown.remainingTime
      };
    }
    const ipCooldown = await this.checkCooldown(ip2, "ip", now);
    if (!ipCooldown.allowed) {
      return {
        allowed: false,
        reason: "IP_COOLDOWN",
        remaining: addressLimit.remaining,
        resetTime: addressLimit.resetTime,
        remainingCooldown: ipCooldown.remainingTime
      };
    }
    return {
      allowed: true,
      remaining: Math.min(addressLimit.remaining, ipLimit.remaining),
      resetTime: Math.min(addressLimit.resetTime, ipLimit.resetTime),
      remainingCooldown: 0
    };
  }
  async consumeBothLimits(address, ip2, maxRequests = 3, windowMs = 60 * 60 * 1000) {
    const now = new Date;
    const windowStart = new Date(now.getTime() - windowMs);
    const addressLimit = await this.consumeRateLimit(address.toLowerCase(), "address", maxRequests, windowStart, now);
    if (!addressLimit.allowed) {
      return {
        allowed: false,
        reason: "ADDRESS_RATE_LIMIT",
        remaining: addressLimit.remaining,
        resetTime: addressLimit.resetTime
      };
    }
    const ipLimit = await this.consumeRateLimit(ip2, "ip", maxRequests, windowStart, now);
    if (!ipLimit.allowed) {
      return {
        allowed: false,
        reason: "IP_RATE_LIMIT",
        remaining: ipLimit.remaining,
        resetTime: ipLimit.resetTime
      };
    }
    return {
      allowed: true,
      remaining: Math.min(addressLimit.remaining, ipLimit.remaining),
      resetTime: Math.min(addressLimit.resetTime, ipLimit.resetTime)
    };
  }
  async setCooldown(identifier, identifierType, cooldownMs) {
    const cooldownUntil = new Date(Date.now() + cooldownMs);
    await faucetDb.insert(faucetRateLimits).values({
      identifier: identifierType === "address" ? identifier.toLowerCase() : identifier,
      identifierType,
      requestCount: 0,
      windowStart: new Date,
      lastRequestTime: new Date,
      cooldownUntil
    }).onConflictDoUpdate({
      target: [faucetRateLimits.identifier, faucetRateLimits.identifierType],
      set: {
        cooldownUntil,
        lastRequestTime: new Date
      }
    });
  }
  async checkRateLimit(identifier, identifierType, maxRequests, windowStart, now) {
    const record = await faucetDb.query.faucetRateLimits.findFirst({
      where: and(eq(faucetRateLimits.identifier, identifierType === "address" ? identifier.toLowerCase() : identifier), eq(faucetRateLimits.identifierType, identifierType))
    });
    if (!record || record.windowStart < windowStart) {
      return {
        allowed: true,
        remaining: maxRequests - 1,
        resetTime: now.getTime() + 60 * 60 * 1000
      };
    }
    if (record.requestCount >= maxRequests) {
      return {
        allowed: false,
        remaining: 0,
        resetTime: record.windowStart.getTime() + 60 * 60 * 1000
      };
    }
    return {
      allowed: true,
      remaining: maxRequests - record.requestCount - 1,
      resetTime: record.windowStart.getTime() + 60 * 60 * 1000
    };
  }
  async consumeRateLimit(identifier, identifierType, maxRequests, windowStart, now) {
    const record = await faucetDb.query.faucetRateLimits.findFirst({
      where: and(eq(faucetRateLimits.identifier, identifierType === "address" ? identifier.toLowerCase() : identifier), eq(faucetRateLimits.identifierType, identifierType))
    });
    if (!record || record.windowStart < windowStart) {
      await faucetDb.insert(faucetRateLimits).values({
        identifier: identifierType === "address" ? identifier.toLowerCase() : identifier,
        identifierType,
        requestCount: 1,
        windowStart: now,
        lastRequestTime: now
      }).onConflictDoUpdate({
        target: [faucetRateLimits.identifier, faucetRateLimits.identifierType],
        set: {
          requestCount: 1,
          windowStart: now,
          lastRequestTime: now
        }
      });
      return {
        allowed: true,
        remaining: maxRequests - 1,
        resetTime: now.getTime() + 60 * 60 * 1000
      };
    }
    if (record.requestCount >= maxRequests) {
      return {
        allowed: false,
        remaining: 0,
        resetTime: record.windowStart.getTime() + 60 * 60 * 1000
      };
    }
    await faucetDb.update(faucetRateLimits).set({
      requestCount: record.requestCount + 1,
      lastRequestTime: now
    }).where(and(eq(faucetRateLimits.identifier, identifierType === "address" ? identifier.toLowerCase() : identifier), eq(faucetRateLimits.identifierType, identifierType)));
    return {
      allowed: true,
      remaining: maxRequests - record.requestCount - 1,
      resetTime: record.windowStart.getTime() + 60 * 60 * 1000
    };
  }
  async checkCooldown(identifier, identifierType, now) {
    const record = await faucetDb.query.faucetRateLimits.findFirst({
      where: and(eq(faucetRateLimits.identifier, identifierType === "address" ? identifier.toLowerCase() : identifier), eq(faucetRateLimits.identifierType, identifierType))
    });
    if (!record || !record.cooldownUntil || record.cooldownUntil <= now) {
      return {
        allowed: true,
        remainingTime: 0
      };
    }
    const remainingTime = record.cooldownUntil.getTime() - now.getTime();
    return {
      allowed: false,
      remainingTime
    };
  }
}
