// src/controllers/faucet.controller.ts
class FaucetController {
  rateLimitService;
  constructor() {
    this.rateLimitService = RateLimitService.getInstance();
  }
  async requestNativeTokens(address, chainId, clientIP) {
    try {
      if (!address || !address.startsWith("0x") || address.length !== 42) {
        return {
          success: false,
          error: "Invalid address format"
        };
      }
      const rateLimitResult = await this.rateLimitService.checkBothLimits(address, clientIP);
      if (!rateLimitResult.allowed) {
        const reason = rateLimitResult.reason || "Rate limit exceeded";
        return {
          success: false,
          error: `Rate limit exceeded: ${reason}`
        };
      }
      return {
        success: false,
        error: "Faucet service not yet implemented"
      };
    } catch (error) {
      console.error("Native faucet request error:", error);
      return {
        success: false,
        error: error instanceof Error ? error.message : "Internal server error"
      };
    }
  }
  async requestTokens(address, tokenAddress, chainId, clientIP, userAgent) {
    try {
      if (!address || !tokenAddress) {
        return {
          success: false,
          error: "Address and tokenAddress are required"
        };
      }
      if (!address.startsWith("0x") || address.length !== 42) {
        return {
          success: false,
          error: "Invalid address format"
        };
      }
      if (!tokenAddress.startsWith("0x") || tokenAddress.length !== 42) {
        return {
          success: false,
          error: "Invalid token address format"
        };
      }
      return {
        success: false,
        error: "Faucet service not yet implemented"
      };
    } catch (error) {
      console.error("Faucet request error:", error);
      return {
        success: false,
        error: error?.message || "Failed to process faucet request"
      };
    }
  }
  async getFaucetAddress(chainId) {
    try {
      return {
        success: false,
        error: "Faucet service not yet implemented"
      };
    } catch (error) {
      console.error("Error getting faucet address:", error);
      return {
        success: false,
        error: error?.message || "Failed to get faucet address"
      };
    }
  }
  async getFaucetHistory(address, chainId, limit = 50) {
    try {
      const conditions = [];
      if (address && chainId) {
        conditions.push(and(sql`LOWER(${faucetRequests.requesterAddress}) = LOWER(${address})`, eq(faucetRequests.chainId, chainId)));
      } else if (address) {
        conditions.push(sql`LOWER(${faucetRequests.requesterAddress}) = LOWER(${address})`);
      } else if (chainId) {
        conditions.push(eq(faucetRequests.chainId, chainId));
      }
      const results = await faucetDb.select().from(faucetRequests).where(conditions.length > 0 ? and(...conditions) : undefined).orderBy(faucetRequests.requestTimestamp).limit(limit);
      const serializedResults = results.map((record) => ({
        ...record,
        amount: record.amount ? record.amount.toString() : "0",
        gasUsed: record.gasUsed ? record.gasUsed.toString() : null,
        gasPrice: record.gasPrice ? record.gasPrice.toString() : null
      }));
      return {
        success: true,
        data: serializedResults
      };
    } catch (error) {
      console.error("Error getting faucet history:", error);
      return {
        success: false,
        error: error?.message || "Failed to get faucet history"
      };
    }
  }
  async recordFaucetRequest(request) {
    try {
      const result = await faucetDb.insert(faucetRequests).values(request).returning({ id: faucetRequests.id });
      return result[0]?.id || null;
    } catch (error) {
      console.error("Failed to record faucet request:", error);
      return null;
    }
  }
  async updateFaucetRequest(id, updates) {
    try {
      const updateData = {};
      if (updates.status)
        updateData.status = updates.status;
      if (updates.transactionHash)
        updateData.transactionHash = updates.transactionHash.toLowerCase();
      if (updates.amount)
        updateData.amount = updates.amount;
      if (updates.amountFormatted)
        updateData.amountFormatted = updates.amountFormatted;
      if (updates.tokenSymbol)
        updateData.tokenSymbol = updates.tokenSymbol;
      if (updates.tokenDecimals)
        updateData.tokenDecimals = updates.tokenDecimals;
      if (updates.errorMessage)
        updateData.errorMessage = updates.errorMessage;
      if (updates.completedTimestamp)
        updateData.completedTimestamp = updates.completedTimestamp;
      if (Object.keys(updateData).length === 0) {
        return false;
      }
      await faucetDb.update(faucetRequests).set(updateData).where(eq(faucetRequests.id, parseInt(id)));
      return true;
    } catch (error) {
      console.error("Failed to update faucet request:", error);
      return false;
    }
  }
}
