// src/index.ts
var app2 = new Elysia().use(cors({
  origin: [
    /^http:\/\/localhost:\d+$/,
    /^https:\/\/.*\.vercel\.app$/,
    /^https:\/\/.*\.netlify\.app$/,
    /^https:\/\/.*\.scalex\.money$/
  ],
  credentials: true,
  allowedHeaders: ["Content-Type", "Authorization"],
  methods: ["GET", "POST", "PUT", "DELETE", "OPTIONS", "PATCH"]
})).use(opentelemetry()).use(openapi({
  path: "/docs",
  documentation: {
    info: {
      title: "Envio API Documentation",
      version: "1.0.0",
      description: "API for querying blockchain events from Envio indexer"
    },
    tags: [
      { name: "Market", description: "Market and trading endpoints" },
      { name: "Orders", description: "Order management endpoints" },
      { name: "Trading", description: "Trading data endpoints" },
      { name: "Currency", description: "Currency information endpoints" },
      { name: "Cross-Chain", description: "Cross-chain transfer and token mapping endpoints" },
      { name: "Lending", description: "Lending protocol and dashboard endpoints" },
      { name: "Faucet", description: "Faucet endpoints for testnet tokens" }
    ]
  }
})).onError(({ code, error, set: set2 }) => {
  if (code === "VALIDATION") {
    set2.status = 400 /* BAD_REQUEST */;
    const parsedError = JSON.parse(error.message);
    const errorMsg = `Validation error: ${parsedError.message}`;
    return createErrorResponse(errorMsg, 400 /* BAD_REQUEST */);
  }
  if (code === "NOT_FOUND") {
    set2.status = 404 /* NOT_FOUND */;
    return createErrorResponse("Route not found", 404 /* NOT_FOUND */);
  }
  set2.status = 500 /* INTERNAL_SERVER_ERROR */;
  return createErrorResponse(error instanceof Error ? error.message : "Internal Server Error", 500 /* INTERNAL_SERVER_ERROR */);
}).get("/", () => ({
  message: "Envio API Server",
  status: "running",
  version: "1.0.0",
  documentation: "/docs"
})).get("/health", () => ({
  status: "healthy",
  timestamp: new Date().toISOString()
}));
app2.use(marketRoutes);
app2.use(currencyRoutes);
app2.use(tradeRoutes);
app2.use(faucetRoutes);
app2.use(crosschainRoutes);
app2.use(lendingRoutes);
app2.listen(app.port);
console.log(`\uD83E\uDD8A Elysia is running at ${app2.server?.hostname}:${app2.server?.port}`);
console.log(`\uD83D\uDCDA Documentation available at http://localhost:${app.port}/docs`);
